import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const _=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"immersive-translate-course/glossary.md","filePath":"immersive-translate-course/docs/glossary.md"}'),s={name:"immersive-translate-course/glossary.md"};function i(n,t,l,o,c,m){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书 29 个概念，每个一句话。按首教章的大致顺序排列；点击任一术语可回到 sidebar 找到对应章节。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>双语对照</td><td>bilingual display</td><td>原文不动、译文紧跟其下逐段显示的翻译呈现方式。</td></tr><tr><td>DOM 树</td><td>DOM tree</td><td>浏览器把 HTML 解析成的活对象树，页面上每个标签是树上一个节点。</td></tr><tr><td>块级元素</td><td>block-level element</td><td>默认独占一行显示的元素（段落、标题、列表项），页面的段落感由它们组成。</td></tr><tr><td>内联元素</td><td>inline element</td><td>默认待在行内不换行的元素（加粗、链接、行内代码）。</td></tr><tr><td>可译块</td><td>translatable block</td><td>直接持有文字的最小块级元素，双语引擎抽取、翻译、插入的基本单位。</td></tr><tr><td>直接文本</td><td>direct text</td><td>一个节点自己名下的文本，不含更深层子块里的文本。</td></tr><tr><td>跳过规则</td><td>skip rules</td><td>判定某节点不该翻译的规则清单（代码块、脚本、纯符号、过短文本）。</td></tr><tr><td>树遍历</td><td>tree traversal</td><td>从根递归走完整棵树、给每个节点分类的算法——文件系统递归遍历的 DOM 版。</td></tr><tr><td>兄弟节点插入</td><td>sibling insertion</td><td>把新节点插到某节点的旁边（同级）而非它里面，原文子树零接触。</td></tr><tr><td>依赖注入</td><td>dependency injection</td><td>把「翻译服务」从引擎内部抽出来当参数传进去，引擎只认接口不认具体服务。</td></tr><tr><td>假翻译器</td><td>fake translator</td><td>确定性的假翻译函数：输入固定输出就固定，让全链路离线可测。</td></tr><tr><td>内联切分</td><td>inline splitting</td><td>按内联边界把一个段落拆成片段分别翻译，再按原结构拼回。</td></tr><tr><td>占位标记</td><td>placeholder</td><td>用翻译过程不会破坏的记号暂代内联标签，译文回来后替换回真实节点。</td></tr><tr><td>链接密度</td><td>link density</td><td>一块文字里链接字符占总字符的比例，高到离谱多半是导航或目录。</td></tr><tr><td>文字密度</td><td>text mass</td><td>一个区域里可译字符的总量，主内容识别里当区域的「分量」用。</td></tr><tr><td>启发式</td><td>heuristic</td><td>用经验规则猜答案的方法：快、够用，但不保证全对。</td></tr><tr><td>并发上限</td><td>concurrency limit</td><td>同时最多允许几个请求在飞的容量闸门，超出的排队等待。</td></tr><tr><td>批量接口</td><td>batch API</td><td>一次调用收发一批文本的接口形态，条数与顺序一一对应，摊薄每次往返的固定开销。</td></tr><tr><td>去重</td><td>dedup</td><td>同一轮送翻前把相同文本合并成一句，重复段落只付一次钱。</td></tr><tr><td>内容寻址缓存</td><td>content-addressed cache</td><td>用内容的哈希当键的缓存，同样的段落永远命中同一条。</td></tr><tr><td>管线组装</td><td>pipeline assembly</td><td>把抽取、翻译、渲染三道工序接成一条流水线，一次调用跑完全程并返回成绩单。</td></tr><tr><td>幂等</td><td>idempotent</td><td>同一操作做一次和做多次结果相同，重复渲染不产生重复译文。</td></tr><tr><td>MutationObserver</td><td>—</td><td>浏览器提供的「DOM 变了就通知我」的监听接口。</td></tr><tr><td>增量抽取</td><td>incremental extraction</td><td>只抽「新上树的子树」里的可译块、老块不重翻的增量口径——观察者对「新」的定义。</td></tr><tr><td>自触发循环</td><td>self-triggering loop</td><td>自己插入的节点又触发自己的监听器，译文生译文直至页面卡死。</td></tr><tr><td>标记属性</td><td>marker attribute</td><td>插入译文节点时打上的 data-* 属性，引擎靠它认出自己的产出。</td></tr><tr><td>重排</td><td>reflow</td><td>浏览器因 DOM 变化重新计算页面布局的过程，大规模重排是卡顿来源。</td></tr><tr><td>content script</td><td>—</td><td>浏览器扩展注入到网页里运行的脚本，引擎在真浏览器里的落脚点。</td></tr><tr><td>manifest</td><td>—</td><td>扩展的身份证兼配置清单，浏览器靠它认识你的扩展。</td></tr></tbody></table>',3)])])}const h=d(s,[["render",i]]);export{_ as __pageData,h as default};
